// Automatic database setup: creates the database (if missing), applies pending migrations,
// and loads sample data into an empty database. Used by `npm start` and scripts/db.js.
const fs = require('fs'), path = require('path');
const root = path.join(__dirname, '..', 'db');
const files = d => fs.readdirSync(path.join(root, d)).filter(f => f.endsWith('.sql')).sort();
const read = (d, f) => fs.readFileSync(path.join(root, d, f), 'utf8');
const client = url => new (require('pg').Client)({ connectionString: url });
const q = s => '"' + s.replace(/"/g, '""') + '"';

// 1. Create the database named in DATABASE_URL if it does not exist yet.
async function ensureDatabase(url) {
  const probe = client(url);
  try { await probe.connect(); await probe.end(); return false; }
  catch (e) { if (e.code !== '3D000') throw e; }          // 3D000 = database does not exist
  if (process.env.AUTO_CREATE_DB === 'false') throw new Error('Database does not exist and AUTO_CREATE_DB=false. Create it first.');
  const u = new URL(url), name = decodeURIComponent(u.pathname.slice(1));
  u.pathname = '/postgres';
  const admin = client(u.toString());
  await admin.connect();
  try { await admin.query('CREATE DATABASE ' + q(name)); console.log(`Created database "${name}"`); }
  catch (e) { throw new Error(`Could not create database "${name}" (${e.message}). Create it manually or use an account with CREATEDB.`); }
  finally { await admin.end(); }
  return true;
}

// 2. Apply migrations that have not been recorded yet (schema, constraints, trigger function, view).
async function migrate(c) {
  await c.query('CREATE TABLE IF NOT EXISTS schema_migrations (name TEXT PRIMARY KEY, applied_at TIMESTAMPTZ DEFAULT now())');
  for (const f of files('migrations')) {
    if ((await c.query('SELECT 1 FROM schema_migrations WHERE name=$1', [f])).rowCount) { console.log('skip     ' + f); continue; }
    await c.query('BEGIN');
    try {
      await c.query(read('migrations', f));
      await c.query('INSERT INTO schema_migrations(name) VALUES ($1)', [f]);
      await c.query('COMMIT'); console.log('migrated ' + f);
    } catch (e) { await c.query('ROLLBACK'); throw e; }
  }
}

// 3. Load sample data (always with force, or only when the database has no data yet).
async function seed(c, force) {
  if (!force) {
    const n = await c.query('SELECT (SELECT COUNT(*) FROM property) + (SELECT COUNT(*) FROM app_user) AS n');
    if (Number(n.rows[0].n) > 0) { console.log('seed skipped (database already has data)'); return; }
  }
  for (const f of files('seeds')) { await c.query(read('seeds', f)); console.log('seeded   ' + f); }
}

async function withDb(fn) {
  if (!process.env.DATABASE_URL) throw new Error('DATABASE_URL is not set (copy .env.example to .env).');
  await ensureDatabase(process.env.DATABASE_URL);
  const c = client(process.env.DATABASE_URL);
  await c.connect();
  try { return await fn(c); } finally { await c.end(); }
}

const setup = ({ seed: doSeed = true } = {}) => withDb(async c => { await migrate(c); if (doSeed) await seed(c, false); });
const reset = () => withDb(async c => {
  await c.query('DROP SCHEMA public CASCADE; CREATE SCHEMA public;');
  await migrate(c); await seed(c, true);
});

// 4. One combined SQL file for psql / pgAdmin users (works on an empty database).
function bundle() {
  const out = ['-- BoardTrack full setup (generated by `npm run db:bundle`). Run on an EMPTY database:',
    '--   psql -U <user> -d <your_db> -f db/boardtrack_full_setup.sql', 'BEGIN;',
    'CREATE TABLE IF NOT EXISTS schema_migrations (name TEXT PRIMARY KEY, applied_at TIMESTAMPTZ DEFAULT now());'];
  for (const f of files('migrations')) out.push(`-- ===== migration ${f} =====`, read('migrations', f),
    `INSERT INTO schema_migrations(name) VALUES ('${f}') ON CONFLICT DO NOTHING;`);
  for (const f of files('seeds')) out.push(`-- ===== seed ${f} =====`, read('seeds', f));
  out.push('COMMIT;');
  const target = path.join(root, 'boardtrack_full_setup.sql');
  fs.writeFileSync(target, out.join('\n') + '\n'); return target;
}
module.exports = { setup, reset, withDb, migrate, seed, bundle, ensureDatabase };
